+package org.apache.samza.operators.impl;
+
+import java.util.Collection;
+import java.util.Collections;
+import java.util.concurrent.CompletionStage;
+import java.util.concurrent.ExecutionException;
+import org.apache.samza.SamzaException;
+import org.apache.samza.context.Context;
+import org.apache.samza.operators.functions.AsyncFlatMapFunction;
+import org.apache.samza.operators.spec.AsyncOperatorSpec;
+import org.apache.samza.operators.spec.OperatorSpec;
+import org.apache.samza.task.MessageCollector;
+import org.apache.samza.task.TaskCoordinator;
+
+
+public class AsyncStreamOperatorImpl<M, RM> extends OperatorImpl<M, RM> {
+  private final AsyncOperatorSpec<M, RM> asyncOperatorSpec;
+  private final AsyncFlatMapFunction<M, RM> transformFn;
+
+  AsyncStreamOperatorImpl(AsyncOperatorSpec<M, RM> asyncOperatorSpec) {
+    this.asyncOperatorSpec = asyncOperatorSpec;
+    this.transformFn = asyncOperatorSpec.getTransformFn();
+  }
+  @Override
+  protected void handleInit(Context context) {
+    this.transformFn.init(context);
+  }
+
+  @Override
+  protected Collection<RM> handleMessage(M message, MessageCollector collector, TaskCoordinator coordinator) {

 Review comment:
   this logic looks a bit complex, primarily stemming from these 2 issues; 

   Firstly, we are mixing sync and async-apis in the `OperatorImpl` base-class. 

   ```
   final T onMessage
   final Future[T] onMessageAsync
   protected T handleMessage
   protected Future[T] handleMessageAsync
   ```

   Secondly, the delegation sequence is a bit round-about for operator classes extending this base-class. For sync operators, `BaseClass#onMessageAsync` delegates to `BaseClass#handleMessageAsync` which in-turn delegates to `DerivedClass#handleMessageSync`. For async operators, `BaseClass#onMessageAsync` delegates to `DerivedClass#handleMessageAsync` 

   I would re-think the base class to only expose the async variant. Additionally,  make `handleMessageAsync()` abstract method.

   ```
    final Future[T] onMessageAsync
    abstract Future[T] handleMessageAsync
   ```
   This also un-confuses the delegation sequence; the base method `onMessageAsync` always delegates to `handleMessageAsync` on the derived class.. You may need to add a little bit of boiler-plate to some derived classes, but I think that's an acceptable tradeoff








