+
+    /** Number of failures. */
+    private int failures;
+
+    /** Minimum time of execution. */
+    private long minTime = -1;
+
+    /** Maximum time of execution. */
+    private long maxTime;
+
+    /** Last start time of execution. */
+    private long lastStartTime;
+
+    /** Query history metrics group key. */
