+
+    public Status(boolean success, String message) {
+      this.success = success;
+      this.message = message;
+    }
+  }
+
+  Map<String, Status> memberStatuses;
+  Status clusterConfigStatus;
+
+  public APIResult() {
+    this.memberStatuses = new HashMap<>();
+    this.clusterConfigStatus = null;
+  }
+
+  public void addMemberStatus(String member, String message, boolean success) {
+    this.memberStatuses.put(member, new Status(success, message));
+  }
+
+  public void setClusterConfigPersisted(String message, boolean clusterConfigPersisted) {
+    this.clusterConfigStatus = new Status(clusterConfigPersisted, message);
+  }
+
+  public Map<String, Status> getMemberStatuses() {
+    return memberStatuses;
+  }
+
+  public Status getClusterConfigStatus() {
+    return clusterConfigStatus;
+  }
+
+  public boolean isSuccessfulOnDistributedMembers() {
+    return memberStatuses.values().stream().allMatch(x -> x.success);
+  }
+
+  public boolean isSuccessfullyPersisted() {
+    return clusterConfigStatus != null && clusterConfigStatus.success;
+  }
+
+  public boolean isSuccessful() {
+    return (clusterConfigStatus == null || isSuccessfullyPersisted())

