new file mode 100644
index 00000000000..fbc4448d59c
--- /dev/null
+++ b/components/camel-jbpm/src/main/java/org/apache/camel/component/jbpm/server/CamelKieServerExtension.java
@@ -0,0 +1,224 @@
+/**
