+      } else if (output instanceof PCollectionList<?>) {
+        PCollectionList<?> listOutput = (PCollectionList<?>) output;
+        return IntStream.range(0, listOutput.size())
+            .boxed()
+            .collect(Collectors.toMap(index -> "output_" + index, listOutput::get));
+      } else {
