+    intArrays[0] = null;
+    intArrays[1] = new Integer[] { 0 };
+    intArrays[2] = new Integer[] { 1 };
+
+    Float[][] floatArrays = new Float[rowCount][];
+    floatArrays[0] = new Float[] { 2.0f };
+    floatArrays[1] = null;
+    floatArrays[2] = new Float[] { 3.0f };
+
+    String[][] stringArrays = new String[rowCount][];
+    stringArrays[0] = new String[] { "4" };
+    stringArrays[1] = null;
+    stringArrays[2] = new String[] { "5" };
+
+    insertRows(rowCount, intArrays, floatArrays, stringArrays);
