+    const auto length = array.length();
+    for (int64_t i = 0; i < length; i++) {
+      if (Traits<T>::NotNull(values[i])) {
+        // NaN is not equal to itself
+        local.total += values[i];
+        local.valid_count++;
+      }
+    }
+
+    *state = local;
+  }
+};
+
+template <typename T>
