-//variable templates is c++14
-//template <typename T>
-//constexpr std::size_t variant_size_v = variant_size<T>::value;
-
-template <typename T>
-struct variant_size<const T>
-    : variant_size<T> {};
-
-template <typename T>
-struct variant_size<volatile T>
-    : variant_size<T> {};
